'use client';

// WorkflowsGallery — the "Workflows" hub: a card per workflow, grouped Platform
// services · Foundation · Tier 1. The catalog of PROCEDURES (distinct from the
// Worksheets hub, which is the library of RESULTS a workflow produces). Shared by
// the /workflows-hub route and the Scope inline hub; the caller owns `onOpen`.

import { ArrowRight, Boxes, Database, FileText } from 'lucide-react';
import { PORTFOLIO_WORKFLOWS, type PortfolioWorkflowDef, type PortfolioWorkflowGroup } from '@/shared/workflow-engine/templates/portfolio/portfolio-workflows';
import { NEU } from '@/components/neumorphic-sidebar';

const GROUPS: { id: PortfolioWorkflowGroup; label: string; Icon: typeof Boxes }[] = [
  { id: 'platform', label: 'Platform services', Icon: Boxes },
  { id: 'foundation', label: 'Foundation', Icon: Database },
  { id: 'tier1', label: 'Tier 1', Icon: FileText },
];

export function WorkflowsGallery({ subtitle, onOpen, dark = false }: {
  subtitle?: string;
  onOpen: (def: PortfolioWorkflowDef) => void;
  dark?: boolean;
}) {
  return (
    <div style={{ background: dark ? 'transparent' : NEU.bg, minHeight: '100%', padding: '32px 36px' }}>
      <style>{`.wf-card:hover { transform: translateY(-2px); box-shadow: ${NEU.shadowOut}; }`}</style>
      <div style={{ maxWidth: 1100, margin: '0 auto' }}>
        <div style={{ fontSize: 22, fontWeight: 750, color: NEU.text, letterSpacing: '-0.02em' }}>Workflows</div>
        {subtitle && <div style={{ margin: '6px 0 8px', fontSize: 13, color: NEU.muted }}>{subtitle}</div>}

        {GROUPS.map(({ id, label, Icon }) => {
          const items = PORTFOLIO_WORKFLOWS.filter((w) => w.group === id);
          if (items.length === 0) return null;
          return (
            <div key={id} style={{ marginTop: 26 }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 13 }}>
                <span style={{ width: 24, height: 24, borderRadius: 7, background: NEU.surface, boxShadow: NEU.shadowSm, display: 'grid', placeItems: 'center', color: NEU.accent }}><Icon size={14} /></span>
                <span style={{ fontSize: 11.5, fontWeight: 700, letterSpacing: '0.05em', textTransform: 'uppercase', color: NEU.muted }}>{label}</span>
                <span style={{ fontSize: 11, color: NEU.faint, fontWeight: 600 }}>{items.length}</span>
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: 16 }}>
                {items.map((w) => (
                  <button
                    key={w.id}
                    onClick={() => onOpen(w)}
                    className="wf-card"
                    style={{ textAlign: 'left', border: 'none', cursor: 'pointer', background: NEU.surface, borderRadius: 16, padding: 18, boxShadow: NEU.shadowSm, display: 'flex', flexDirection: 'column', gap: 10, transition: 'transform 160ms ease, box-shadow 160ms ease' }}
                  >
                    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                      <span style={{ width: 38, height: 38, borderRadius: 12, background: NEU.bg, boxShadow: NEU.shadowSm, display: 'grid', placeItems: 'center', color: NEU.accent }}><Icon size={18} /></span>
                      <ArrowRight size={16} style={{ color: NEU.faint }} />
                    </div>
                    <div style={{ fontSize: 14.5, fontWeight: 700, color: NEU.text, letterSpacing: '-0.01em' }}>{w.name.replace(/^Platform Services · /, '')}</div>
                    <div style={{ fontSize: 12, lineHeight: 1.5, color: NEU.muted }}>{w.sub}</div>
                  </button>
                ))}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
