'use client';

// Standalone Workflows hub route — the gallery of workflow procedures, reached
// from the GlobalTopNav "Workflows" pill. Picking a workflow opens it INSIDE the
// Scope workspace as an inline tab (pageKey `workflow:<id>`) — same experience as
// the Scope sidebar's Workflows hub — rather than a bare standalone route, so it
// keeps the workspace chrome + chat and runs in-page.

import { useRouter } from 'next/navigation';
import { useAtomValue, useSetAtom } from 'jotai';
import { WorkflowsGallery } from '@/features/workflows-hub/workflows-gallery';
import { openWorkspaceWindowAtom } from '@/shared/stores/workspace-store';
import { selectedClientAtom } from '@/shared/stores/nav-store';

export default function WorkflowsHubPage() {
  const router = useRouter();
  const openWindow = useSetAtom(openWorkspaceWindowAtom);
  const client = useAtomValue(selectedClientAtom);
  return (
    <div className="h-full overflow-auto">
      <WorkflowsGallery
        subtitle={`The standardized procedures — pick one to view its process, run it, and review the result. ${client}.`}
        onOpen={(def) => {
          openWindow({ pageKey: `workflow:${def.id}`, title: def.name.replace(/^Platform Services · /, '') });
          router.push('/');
        }}
      />
    </div>
  );
}
